const fs = require('fs');
const pkg = JSON.parse(fs.readFileSync('/workspace/package.json', 'utf8'));

// Update dependencies
if (pkg.dependencies) {
  Object.keys(pkg.dependencies).forEach(key => {
    pkg.dependencies[key] = '0.0.1';
  });
}

// Update devDependencies
if (pkg.devDependencies) {
  Object.keys(pkg.devDependencies).forEach(key => {
    pkg.devDependencies[key] = '0.0.1';
  });
}

// Update peerDependencies
if (pkg.peerDependencies) {
  Object.keys(pkg.peerDependencies).forEach(key => {
    pkg.peerDependencies[key] = '0.0.1';
  });
}

fs.writeFileSync('/workspace/package.json', JSON.stringify(pkg, null, 2));
console.log('Updated all dependency versions to 0.0.1');
"
```

This script will:
1. Read the package.json file
2. Change all versions in `dependencies`, `devDependencies`, and `peerDependencies` to "0.0.1"
3. Write the modified file back with proper formatting

